pub open spec fn choice_for(t:Trace,v:u64,n:u64,term:u64) -> bool {t.choices.contains(Choice{node:v,term,candidate:n})}
pub open spec fn evidence(t:Trace,n:int,v:u64,term:u64) -> bool {
